		return n
	}
	ans := 0
	for i := 0; i < n-1; i++ {
		freq := make(map[pair]int)
		for j := i + 1; j < n; j++ {
			x1, y1, x2, y2 := points[i][0], points[i][1], points[j][0], points[j][1]
			dx, dy := x2-x1, y2-y1
			g := gcd(dx, dy)
			p := pair{dx / g, dy / g}
			freq[p]++
			ans = max(ans, freq[p]+1)
		}
	}
	return ans
}

